/*!
 * Themeasy — Table of Contents
 *
 * Builds and drives the .tms-table-of-contents widget:
 *   - Scans the page (or the configured containers) for the chosen heading
 *     levels, assigns stable slugified anchor ids and renders the nested
 *     link list (createElement/textContent only — heading text is page data)
 *   - Scrollspy: tracks the section being read and slides the rail indicator
 *     by writing the --tms-table-of-contents-marker-y/-h custom properties
 *     (CSS transitions do the motion)
 *   - Reading progress: writes the 0-1 --tms-table-of-contents-progress
 *     fraction consumed by the header hairline's scaleX fill
 *   - Smooth-scrolls clicks with a scroll-margin offset (sticky headers),
 *     updates the URL hash and moves focus to the target heading
 *   - Collapse chevron (grid-rows CSS animation) with optional collapsed
 *     start on load / on mobile — no-JS visitors always see the list open
 *   - Below the minimum heading count the widget marks itself --empty
 *     (hidden on the frontend, placeholder note in the editor)
 *   - No vendor dependencies. In the editor preview (--static) only the scan
 *     and list build run — scrollspy, clicks and collapse stay inert — and
 *     reduced motion drops smooth scrolling (CSS drops the transitions).
 *
 * Namespace:    window.Themeasy.tableOfContents
 * Pattern:      IIFE + onDomReady() + boot()
 * Idempotent:   each element tears down its prior instance before rebinding.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.tableOfContents = window.Themeasy.tableOfContents || {}

  // ------------------------------------------------------------------------
  // Selectors & constants
  // ------------------------------------------------------------------------
  const SELECTOR_WIDGET = '.tms-table-of-contents'
  const SELECTOR_LIST = '.tms-table-of-contents__list'
  const SELECTOR_PANEL = '.tms-table-of-contents__panel'
  const SELECTOR_TOGGLE = '.tms-table-of-contents__toggle'
  const SELECTOR_PROGRESS = '.tms-table-of-contents__progress'
  const SELECTOR_LINK = '.tms-table-of-contents__link'

  const CLASS_STATIC = 'tms-table-of-contents--static' // editor preview = inert
  const CLASS_SPY = 'tms-table-of-contents--spy'
  const CLASS_READY = 'tms-table-of-contents--ready'
  const CLASS_EMPTY = 'tms-table-of-contents--empty'
  const CLASS_INSTANT = 'tms-table-of-contents--instant'
  const CLASS_COLLAPSED = 'tms-table-of-contents--collapsed'
  const CLASS_READING = 'tms-table-of-contents--reading'
  const CLASS_LINK_ACTIVE = 'tms-table-of-contents__link--active'

  const PROP_MARKER_Y = '--tms-table-of-contents-marker-y'
  const PROP_MARKER_H = '--tms-table-of-contents-marker-h'
  const PROP_PROGRESS = '--tms-table-of-contents-progress'

  // The reading line sits slightly below the scroll offset so a heading
  // counts as "reached" the moment it settles under a sticky header.
  const ACTIVATION_PAD = 8

  // Elementor's default responsive breakpoints (mobile ends at 767, tablet at
  // 1024) — used to pick the active Scroll Offset and the collapse-on-mobile
  // default. Custom kit breakpoints are not read; these cover the stock setup.
  const MOBILE_QUERY = '(max-width: 767px)'
  const TABLET_QUERY = '(max-width: 1024px)'

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  function prefersReducedMotion() {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches
  }

  /**
   * Turn a heading's text into an anchor-safe slug. NFKD splits accented Latin
   * letters into base + combining mark so the diacritic strip folds them
   * (café -> cafe), while the unicode-aware whitelist keeps CJK / Cyrillic /
   * Greek etc. intact instead of collapsing every non-Latin heading to
   * "section" — encodeURIComponent handles those bytes in the href.
   *
   * @param {string} text Heading text.
   * @returns {string} Slug (never empty).
   */
  function slugify(text) {
    const slug = text
      .toLowerCase()
      .trim()
      .normalize('NFKD')
      .replace(/\p{Diacritic}/gu, '')
      .replace(/[^\p{L}\p{N}\s_-]/gu, '')
      .replace(/[\s_]+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-+|-+$/g, '')

    return slug || 'section'
  }

  /**
   * Reuse a heading's existing id or assign a unique slugified one. Existing
   * ids win so hand-written anchors and other TOC instances stay stable;
   * generated ids are namespaced so heading text can never squat a global
   * name another script might read (DOM clobbering).
   *
   * @param {HTMLElement} heading Heading element.
   * @param {Set<string>} used Ids already claimed in this scan.
   * @returns {string} The heading's id.
   */
  function ensureHeadingId(heading, used) {
    const existing = heading.getAttribute('id')

    if (existing) {
      used.add(existing)
      return existing
    }

    const base = 'tms-toc-' + slugify(heading.textContent)
    let candidate = base
    let suffix = 2

    while (used.has(candidate) || document.getElementById(candidate)) {
      candidate = base + '-' + suffix
      suffix++
    }

    heading.setAttribute('id', candidate)
    used.add(candidate)

    return candidate
  }

  /**
   * closest() guarded against invalid user-provided selectors.
   *
   * @param {HTMLElement} el Element to test.
   * @param {string} selector CSS selector (may be invalid).
   * @returns {Element|null} Matched ancestor or null.
   */
  function safeClosest(el, selector) {
    if (!selector) return null

    try {
      return el.closest(selector)
    } catch (error) {
      // Invalid user selector — treat as no match.
      return null
    }
  }

  /**
   * Read one of the responsive scroll-offset attributes as a number, or null
   * when it is unset (so the caller can inherit the next-wider breakpoint).
   *
   * @param {HTMLElement} rootEl Widget root.
   * @param {string} attr Attribute name.
   * @returns {number|null} Offset in px, or null when unset.
   */
  function readOffsetAttr(rootEl, attr) {
    const raw = rootEl.getAttribute(attr)

    if (raw === null || raw === '') return null

    const value = parseInt(raw, 10)

    return isNaN(value) ? null : Math.max(0, value)
  }

  /**
   * Read the widget's scan/behavior config from its data attributes.
   *
   * @param {HTMLElement} rootEl Widget root.
   * @returns {Object} Parsed config.
   */
  function readConfig(rootEl) {
    const levelsRaw = rootEl.getAttribute('data-levels') || ''
    const levels = levelsRaw.split(',').map(function (level) {
      return level.trim()
    }).filter(function (level) {
      return /^h[2-6]$/.test(level)
    })

    // Scroll offset is responsive; tablet/mobile inherit the next-wider value
    // when unset, mirroring Elementor's own responsive control model.
    const offsetDesktop = readOffsetAttr(rootEl, 'data-offset')
    const offsetTablet = readOffsetAttr(rootEl, 'data-offset-tablet')
    const offsetMobile = readOffsetAttr(rootEl, 'data-offset-mobile')
    const resolvedDesktop = offsetDesktop === null ? 0 : offsetDesktop
    const resolvedTablet = offsetTablet === null ? resolvedDesktop : offsetTablet

    return {
      levels: levels.length ? levels : ['h2', 'h3'],
      selector: rootEl.getAttribute('data-selector') || '',
      exclude: rootEl.getAttribute('data-exclude') || '',
      min: Math.max(1, parseInt(rootEl.getAttribute('data-min'), 10) || 1),
      nested: rootEl.getAttribute('data-nested') === 'true',
      smooth: rootEl.getAttribute('data-smooth') === 'true',
      offsets: {
        desktop: resolvedDesktop,
        tablet: resolvedTablet,
        mobile: offsetMobile === null ? resolvedTablet : offsetMobile
      },
      collapsed: rootEl.getAttribute('data-collapsed') || ''
    }
  }

  /**
   * Pick the scroll offset for the current viewport from the resolved set.
   *
   * @param {Object} offsets { desktop, tablet, mobile } in px.
   * @returns {number} Active offset.
   */
  function activeOffset(offsets) {
    if (window.matchMedia(MOBILE_QUERY).matches) return offsets.mobile
    if (window.matchMedia(TABLET_QUERY).matches) return offsets.tablet

    return offsets.desktop
  }

  // ------------------------------------------------------------------------
  // Scan & build
  // ------------------------------------------------------------------------

  /**
   * Collect the headings feeding the list, in document order. Headings inside
   * any TOC widget, inside aria-hidden subtrees (cloned content),
   * matching the exclude selector, empty or not rendered are skipped.
   *
   * @param {HTMLElement} rootEl Widget root (skipped from the scan).
   * @param {Object} config Parsed config.
   * @returns {Array<HTMLElement>} Headings in document order.
   */
  function collectHeadings(rootEl, config) {
    let scopes = [document.body]

    if (config.selector) {
      try {
        const found = document.querySelectorAll(config.selector)

        if (found.length) {
          scopes = Array.prototype.slice.call(found)
        }
      } catch (error) {
        // Invalid user selector — fall back to scanning the whole page.
      }
    }

    const levelSelector = config.levels.join(',')
    const seen = new Set()
    const headings = []

    scopes.forEach(function (scope) {
      scope.querySelectorAll(levelSelector).forEach(function (heading) {
        if (seen.has(heading)) return
        seen.add(heading)

        if (heading.closest(SELECTOR_WIDGET)) return
        if (heading.closest('[aria-hidden="true"]')) return
        if (safeClosest(heading, config.exclude)) return
        if (!heading.textContent.trim()) return
        if (!heading.getClientRects().length) return

        headings.push(heading)
      })
    })

    // Multiple scan containers can interleave — restore document order.
    headings.sort(function (a, b) {
      const position = a.compareDocumentPosition(b)

      if (position & Node.DOCUMENT_POSITION_FOLLOWING) return -1
      if (position & Node.DOCUMENT_POSITION_PRECEDING) return 1

      return 0
    })

    return headings
  }

  /**
   * Map headings to list entries, assigning anchor ids along the way.
   *
   * @param {Array<HTMLElement>} headings Collected headings.
   * @returns {Array<Object>} Entries ({ el, id, text, level }).
   */
  function buildEntries(headings) {
    const used = new Set()

    return headings.map(function (heading) {
      return {
        el: heading,
        id: ensureHeadingId(heading, used),
        text: heading.textContent.trim(),
        level: parseInt(heading.tagName.charAt(1), 10)
      }
    })
  }

  /**
   * Render the (optionally nested) link list. DOM is built exclusively via
   * createElement/textContent — heading text is arbitrary page content.
   *
   * @param {HTMLElement} listEl Root ol element (cleared first).
   * @param {Array<Object>} entries List entries.
   * @param {boolean} nested Indent sub-levels (false = flat list).
   * @returns {Array<HTMLElement>} The links, in entry order.
   */
  function renderList(listEl, entries, nested) {
    listEl.replaceChildren()

    const links = []

    // Seeded with a sentinel below every heading level, so the first entry
    // always anchors at the root regardless of its tag. Nesting is relative
    // to appearance order: an h3 seen before any h2 sits at the root, and a
    // later h2 also sits at the root beside it (no negative indentation).
    const stack = [{ level: -1, list: listEl, li: null }]

    entries.forEach(function (entry) {
      const level = nested ? entry.level : 0

      while (stack.length > 1 && level <= stack[stack.length - 1].level) {
        stack.pop()
      }

      const top = stack[stack.length - 1]

      // Lazily open a sublist under the parent item on the first deeper entry.
      if (!top.list) {
        top.list = document.createElement('ol')
        top.list.className = 'tms-table-of-contents__sublist'
        top.li.appendChild(top.list)
      }

      const item = document.createElement('li')
      item.className = 'tms-table-of-contents__item'

      const link = document.createElement('a')
      link.className = 'tms-table-of-contents__link'
      link.href = '#' + encodeURIComponent(entry.id)
      link.textContent = entry.text

      item.appendChild(link)
      top.list.appendChild(item)
      links.push(link)

      stack.push({ level: level, list: null, li: item })
    })

    return links
  }

  // ------------------------------------------------------------------------
  // Scrollspy & reading progress
  // ------------------------------------------------------------------------

  /**
   * Cache the headings' absolute page offsets (re-run on any layout change).
   *
   * @param {Object} instance Widget instance.
   */
  function cacheTops(instance) {
    instance.tops = instance.entries.map(function (entry) {
      return entry.el.getBoundingClientRect().top + window.scrollY
    })
  }

  /**
   * Move the rail indicator to a link by writing the marker custom props —
   * the CSS transition does the sliding.
   *
   * @param {Object} instance Widget instance.
   * @param {HTMLElement} link Active link.
   */
  function applyMarker(instance, link) {
    const panelRect = instance.panelEl.getBoundingClientRect()
    const linkRect = link.getBoundingClientRect()

    instance.rootEl.style.setProperty(PROP_MARKER_Y, (linkRect.top - panelRect.top) + 'px')
    instance.rootEl.style.setProperty(PROP_MARKER_H, linkRect.height + 'px')
  }

  /**
   * Apply the active entry: link class, the --reading root state and the
   * rail indicator position.
   *
   * @param {Object} instance Widget instance.
   * @param {number} index Active entry index (-1 = before the first heading).
   * @param {boolean} force Re-apply geometry even when the index is unchanged.
   */
  function setActive(instance, index, force) {
    const changed = index !== instance.activeIndex

    if (!changed && !force) return

    if (changed && instance.activeIndex >= 0 && instance.links[instance.activeIndex]) {
      instance.links[instance.activeIndex].classList.remove(CLASS_LINK_ACTIVE)
    }

    instance.activeIndex = index

    const active = index >= 0 ? instance.links[index] : null

    instance.rootEl.classList.toggle(CLASS_READING, !!active)

    if (!active) return

    if (changed) {
      active.classList.add(CLASS_LINK_ACTIVE)
    }

    applyMarker(instance, active)
  }

  /**
   * Write the 0-1 reading-progress fraction (first heading → page end).
   *
   * @param {Object} instance Widget instance.
   */
  function updateProgress(instance) {
    if (!instance.hasProgress || !instance.tops.length) return

    const maxScroll = Math.max(1, document.documentElement.scrollHeight - window.innerHeight)
    const start = Math.min(Math.max(0, instance.tops[0] - (window.innerHeight * 0.5)), maxScroll - 1)
    const progress = (window.scrollY - start) / (maxScroll - start)

    instance.rootEl.style.setProperty(PROP_PROGRESS, String(Math.min(1, Math.max(0, progress))))
  }

  /**
   * Recompute the current section from the cached offsets and apply it.
   *
   * @param {Object} instance Widget instance.
   */
  function updateSpy(instance) {
    if (!instance.tops.length) return

    const line = window.scrollY + instance.offset + ACTIVATION_PAD
    let index = -1

    for (let i = 0; i < instance.tops.length; i++) {
      if (instance.tops[i] <= line) {
        index = i
      } else {
        break
      }
    }

    // Snap to the last section once the page bottom is reached, so a short
    // final section still gets its highlight.
    if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2) {
      index = instance.tops.length - 1
    }

    if (instance.hasSpy) {
      setActive(instance, index, instance.forceNextSpy)
    }

    instance.forceNextSpy = false
    updateProgress(instance)
  }

  /**
   * rAF-throttled spy tick for the scroll listener.
   *
   * @param {Object} instance Widget instance.
   */
  function requestTick(instance) {
    if (instance.ticking) return

    instance.ticking = true

    window.requestAnimationFrame(function () {
      instance.ticking = false
      updateSpy(instance)
    })
  }

  /**
   * Apply the active scroll offset to every collected heading as
   * scroll-margin-top — honored by both our smooth scroll and native hash
   * navigation, so headings clear a sticky header on jump.
   *
   * @param {Object} instance Widget instance.
   */
  function applyScrollMargin(instance) {
    instance.entries.forEach(function (entry) {
      entry.el.style.scrollMarginTop = instance.offset + 'px'
    })
  }

  /**
   * Identity + order comparison of two heading-element arrays.
   *
   * @param {Array<HTMLElement>} a First list.
   * @param {Array<HTMLElement>} b Second list.
   * @returns {boolean} True when identical.
   */
  function sameHeadings(a, b) {
    if (a.length !== b.length) return false

    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) return false
    }

    return true
  }

  /**
   * Re-scan the page and, when the heading set changed, rebuild the list in
   * place. This is what catches headings revealed after load — an expanded
   * accordion panel or a switched-to tab — which the initial scan skips as
   * not-yet-rendered. The collapsed state is preserved.
   *
   * @param {Object} instance Widget instance.
   * @returns {boolean} True when the list was rebuilt.
   */
  function rescanEntries(instance) {
    const headings = collectHeadings(instance.rootEl, instance.config)
    const current = instance.entries.map(function (entry) {
      return entry.el
    })

    if (sameHeadings(headings, current)) return false

    // Dropped below the minimum: blank the list and mark empty, but keep the
    // instance alive so a later reveal can refill it.
    if (headings.length < instance.config.min) {
      instance.listEl.replaceChildren()
      instance.entries = []
      instance.links = []
      instance.tops = []
      instance.activeIndex = -1
      instance.rootEl.classList.add(CLASS_EMPTY)
      instance.rootEl.classList.remove(CLASS_READING)
      return true
    }

    instance.entries = buildEntries(headings)
    instance.links = renderList(instance.listEl, instance.entries, instance.config.nested)
    instance.activeIndex = -1
    instance.rootEl.classList.remove(CLASS_EMPTY)
    instance.rootEl.classList.add(CLASS_READY)
    applyScrollMargin(instance)

    return true
  }

  /**
   * Layout changed (resize, images loading, revealed content): refresh the
   * active offset, re-scan for new/removed headings, then re-cache the offsets
   * and force-refresh the indicator geometry.
   *
   * @param {Object} instance Widget instance.
   */
  function refreshGeometry(instance) {
    const offset = activeOffset(instance.config.offsets)

    if (offset !== instance.offset) {
      instance.offset = offset
      applyScrollMargin(instance)
    }

    rescanEntries(instance)
    cacheTops(instance)
    instance.forceNextSpy = true
    updateSpy(instance)
  }

  /**
   * rAF-coalesced refreshGeometry for the high-frequency resize / observer
   * paths, so a burst of layout changes triggers at most one re-scan a frame.
   *
   * @param {Object} instance Widget instance.
   */
  function scheduleGeometry(instance) {
    if (instance.geometryScheduled) return

    instance.geometryScheduled = true

    window.requestAnimationFrame(function () {
      instance.geometryScheduled = false
      refreshGeometry(instance)
    })
  }

  // ------------------------------------------------------------------------
  // Collapse
  // ------------------------------------------------------------------------

  /**
   * Apply the collapsed state (class + aria-expanded).
   *
   * @param {Object} instance Widget instance.
   * @param {boolean} collapsed Collapse (true) or expand (false).
   */
  function setCollapsed(instance, collapsed) {
    instance.rootEl.classList.toggle(CLASS_COLLAPSED, collapsed)

    if (instance.toggleEl) {
      instance.toggleEl.setAttribute('aria-expanded', String(!collapsed))
    }
  }

  // ------------------------------------------------------------------------
  // Instance lifecycle
  // ------------------------------------------------------------------------

  /**
   * Tear down a widget's listeners/observers (idempotent).
   *
   * @param {HTMLElement} rootEl Widget root.
   */
  function destroyInstance(rootEl) {
    const instance = rootEl._tmsTocInstance

    if (!instance) return

    if (instance.onScroll) {
      window.removeEventListener('scroll', instance.onScroll)
    }

    if (instance.onResize) {
      window.removeEventListener('resize', instance.onResize)
    }

    if (instance.resizeObserver) {
      instance.resizeObserver.disconnect()
    }

    if (instance.onClick && instance.listEl) {
      instance.listEl.removeEventListener('click', instance.onClick)
    }

    if (instance.onToggle && instance.toggleEl) {
      instance.toggleEl.removeEventListener('click', instance.onToggle)
    }

    // The widget writes scroll-margin-top onto page headings it doesn't own —
    // clear it on teardown so a reconfigure (or removal) leaves no residue on
    // a heading that drops out of scope. Generated ids are kept: deep links
    // may already point at them.
    if (instance.entries) {
      instance.entries.forEach(function (entry) {
        entry.el.style.removeProperty('scroll-margin-top')
      })
    }

    delete rootEl._tmsTocInstance
  }

  /**
   * Build (or rebuild) a single widget: scan, render the list, then layer
   * the interactive behaviors — which stay off on the editor canvas.
   *
   * @param {HTMLElement} rootEl Widget root.
   */
  function buildInstance(rootEl) {
    // Elementor re-renders widgets in the editor; always tear down first.
    destroyInstance(rootEl)

    const listEl = rootEl.querySelector(SELECTOR_LIST)
    const panelEl = rootEl.querySelector(SELECTOR_PANEL)

    if (!listEl || !panelEl) return

    const config = readConfig(rootEl)
    const entries = buildEntries(collectHeadings(rootEl, config))

    // Below the minimum: keep the shell empty. The frontend hides itself
    // (CSS); the editor canvas shows the placeholder note instead.
    if (entries.length < config.min) {
      listEl.replaceChildren()
      rootEl.classList.add(CLASS_EMPTY)
      rootEl.classList.remove(CLASS_READY, CLASS_READING)
      return
    }

    rootEl.classList.remove(CLASS_EMPTY)

    const links = renderList(listEl, entries, config.nested)

    rootEl.classList.add(CLASS_READY)

    // Editor canvas: the built list IS the preview — scrollspy, clicks and
    // collapse stay inert so nothing fights selection or inline editing.
    if (rootEl.classList.contains(CLASS_STATIC)) return

    const instance = {
      rootEl: rootEl,
      listEl: listEl,
      panelEl: panelEl,
      toggleEl: rootEl.querySelector(SELECTOR_TOGGLE),
      config: config,
      entries: entries,
      links: links,
      tops: [],
      offset: activeOffset(config.offsets),
      activeIndex: -1,
      ticking: false,
      geometryScheduled: false,
      forceNextSpy: false,
      hasSpy: rootEl.classList.contains(CLASS_SPY),
      hasProgress: !!rootEl.querySelector(SELECTOR_PROGRESS),
      onScroll: null,
      onResize: null,
      onClick: null,
      onToggle: null,
      resizeObserver: null
    }

    rootEl._tmsTocInstance = instance

    // Anchor offset: scroll-margin keeps headings clear of sticky headers
    // for both our smooth scroll and native hash navigation.
    applyScrollMargin(instance)

    // ------------------------------------------------------------------------
    // Click-to-scroll.
    // ------------------------------------------------------------------------
    instance.onClick = function (event) {
      const link = event.target.closest(SELECTOR_LINK)

      if (!link || !listEl.contains(link)) return

      const hash = link.getAttribute('href') || ''

      if (hash.charAt(0) !== '#') return

      let id = hash.slice(1)

      try {
        id = decodeURIComponent(id)
      } catch (error) {
        // Malformed sequence — use the raw fragment.
      }

      const target = document.getElementById(id)

      if (!target) return

      event.preventDefault()

      const behavior = (config.smooth && !prefersReducedMotion()) ? 'smooth' : 'auto'

      target.scrollIntoView({ behavior: behavior, block: 'start' })

      if (window.history && window.history.pushState) {
        window.history.pushState(null, '', hash)
      }

      // Keep keyboard/AT context at the destination.
      target.setAttribute('tabindex', '-1')
      target.focus({ preventScroll: true })
    }

    listEl.addEventListener('click', instance.onClick)

    // ------------------------------------------------------------------------
    // Collapse.
    // ------------------------------------------------------------------------
    if (instance.toggleEl) {
      instance.onToggle = function () {
        setCollapsed(instance, !rootEl.classList.contains(CLASS_COLLAPSED))
      }

      instance.toggleEl.addEventListener('click', instance.onToggle)

      const startCollapsed = config.collapsed === 'always' ||
        (config.collapsed === 'mobile' && window.matchMedia(MOBILE_QUERY).matches)

      if (startCollapsed) {
        // Land the initial state without playing the collapse animation.
        rootEl.classList.add(CLASS_INSTANT)
        setCollapsed(instance, true)
        void rootEl.offsetWidth
        rootEl.classList.remove(CLASS_INSTANT)
      }
    }

    // ------------------------------------------------------------------------
    // Scrollspy + reading progress.
    // ------------------------------------------------------------------------
    if (instance.hasSpy || instance.hasProgress) {
      instance.onScroll = function () {
        requestTick(instance)
      }

      instance.onResize = function () {
        scheduleGeometry(instance)
      }

      window.addEventListener('scroll', instance.onScroll, { passive: true })
      window.addEventListener('resize', instance.onResize)

      // Content height changes (images loading, accordions, editors) shift the
      // heading offsets and can reveal headings the initial scan skipped —
      // watch the body, not just the window. Coalesced to one pass per frame.
      if (typeof window.ResizeObserver !== 'undefined') {
        instance.resizeObserver = new ResizeObserver(function () {
          scheduleGeometry(instance)
        })
        instance.resizeObserver.observe(document.body)
      }

      refreshGeometry(instance)
    }

    // ------------------------------------------------------------------------
    // Deep links — generated ids don't exist at the browser's initial hash
    // jump; settle it once the list is built.
    // ------------------------------------------------------------------------
    if (window.location.hash) {
      let hashId = window.location.hash.slice(1)

      try {
        hashId = decodeURIComponent(hashId)
      } catch (error) {
        // Malformed sequence — use the raw fragment.
      }

      const isOwn = entries.some(function (entry) {
        return entry.id === hashId
      })

      if (isOwn) {
        const target = document.getElementById(hashId)

        if (target) {
          window.requestAnimationFrame(function () {
            target.scrollIntoView({ behavior: 'auto', block: 'start' })
          })
        }
      }
    }
  }

  // ------------------------------------------------------------------------
  // Core init
  // ------------------------------------------------------------------------

  /**
   * Initialize table-of-contents widgets within the given scope.
   *
   * @param {ParentNode} [root=document] Scope to query inside.
   */
  window.Themeasy.tableOfContents.init = function (root) {
    const scope = root || document
    const widgets = []

    // The scope may be the widget root itself (editor preview re-init).
    // nodeType, not `instanceof Element`: editor preview nodes come from another realm.
    if (scope.nodeType === 1 && scope.matches(SELECTOR_WIDGET)) {
      widgets.push(scope)
    }

    scope.querySelectorAll(SELECTOR_WIDGET).forEach(function (widget) {
      widgets.push(widget)
    })

    if (!widgets.length) return

    widgets.forEach(buildInstance)
  }

  /**
   * Force a re-scan of the given scope's widgets. Widgets with scrollspy or
   * the reading-progress line self-heal via their ResizeObserver, but a widget
   * with both off never re-scans on its own — call this after revealing
   * headings it should pick up (e.g. from a custom accordion's toggle).
   *
   * @param {ParentNode} [root=document] Scope to query inside.
   */
  window.Themeasy.tableOfContents.rescan = function (root) {
    const scope = root || document
    const widgets = []

    // nodeType, not `instanceof Element`: editor preview nodes come from another realm.
    if (scope.nodeType === 1 && scope.matches(SELECTOR_WIDGET)) {
      widgets.push(scope)
    }

    scope.querySelectorAll(SELECTOR_WIDGET).forEach(function (widget) {
      widgets.push(widget)
    })

    widgets.forEach(function (widget) {
      const instance = widget._tmsTocInstance

      if (instance) {
        refreshGeometry(instance)
      } else {
        buildInstance(widget)
      }
    })
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WIDGET)) {
      window.Themeasy.tableOfContents.init()
    }
  }

  window.Themeasy.tableOfContents.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(boot)
})(window, document)
